import type { ResolvedSdkTarget, SdkSymbolKind } from '@mintlify/models';

import type { SdkPage, SdkPageTarget, SdkReference } from './types.js';

const KIND_DIRS: Record<SdkSymbolKind, string> = {
  package: 'packages',
  class: 'classes',
  interface: 'interfaces',
  enum: 'enums',
  function: 'functions',
  type: 'types',
  variable: 'variables',
  method: 'methods',
  property: 'properties',
};

type SdkTargetRequest = Pick<ResolvedSdkTarget, 'kind' | 'name' | 'parent' | 'namespace'>;

// An explicit namespace (object-form frontmatter) must match the page's exactly;
// a dotted shorthand such as `audio.client.Foo` matches any trailing part of
// the page's namespace.
export function matchesSdkPageTarget(
  pageTarget: SdkPageTarget | undefined,
  target: SdkTargetRequest
): boolean {
  if (!pageTarget) return false;
  if (pageTarget.kind !== target.kind) return false;
  if (target.namespace !== undefined && pageTarget.namespace !== target.namespace) return false;
  const exact = target.namespace !== undefined;
  if (!matchesSdkName(pageTarget.name, pageTarget.namespace, target.name, exact)) return false;
  if (target.parent) {
    return (
      pageTarget.parent !== undefined &&
      matchesSdkName(pageTarget.parent, pageTarget.namespace, target.parent, exact)
    );
  }
  return pageTarget.parent === undefined;
}

function matchesSdkName(
  name: string,
  namespace: string | undefined,
  requested: string,
  exact: boolean
): boolean {
  if (requested === name) return true;
  if (exact || namespace === undefined) return false;
  return `.${namespace}.${name}`.endsWith(`.${requested}`);
}

function matchesSdkPageHeuristic(page: SdkPage, target: SdkTargetRequest): boolean {
  if (target.parent) {
    return (
      page.title === `${target.parent}.${target.name}` ||
      page.slug.endsWith(`/${slugify(target.parent)}/${slugify(target.name)}`)
    );
  }
  // Only slug matches encode the symbol kind; a bare title match could return
  // a same-named symbol of a different kind.
  const dir = KIND_DIRS[target.kind];
  return (
    page.slug === `${dir}/${slugify(target.name)}` ||
    page.slug.endsWith(`/${dir}/${slugify(target.name)}`)
  );
}

function slugify(name: string): string {
  return name.replace(/[^a-zA-Z0-9-_.]+/g, '-').replace(/^-+|-+$/g, '') || 'item';
}

function qualifiedName(target: SdkPageTarget): string {
  const name = target.parent ? `${target.parent}.${target.name}` : target.name;
  return target.namespace ? `${target.namespace}.${name}` : name;
}

// Several pages can match a bare name. When their targets carry namespaces the
// request can be qualified, so that is an error listing the candidates; when
// they do not (TypeDoc has no namespaces), the first match stands as before.
export function findSdkPage(
  reference: SdkReference,
  target: SdkTargetRequest
): SdkPage | undefined {
  const matches = reference.pages.filter((page) => matchesSdkPageTarget(page.target, target));
  if (matches.length > 1) {
    // `package client` names the root package `client` outright even when a
    // `client/` directory also ends in that name; only the shorthand that fits
    // several pages equally is ambiguous.
    const requested = target.parent ? `${target.parent}.${target.name}` : target.name;
    const exact = matches.filter(
      (page) => qualifiedName(page.target as SdkPageTarget) === requested
    );
    if (exact.length === 1) return exact[0];
  }
  if (matches.length > 1 && matches.some((page) => page.target?.namespace)) {
    const candidates = matches.map((page) => qualifiedName(page.target as SdkPageTarget));
    const requested = target.parent ? `${target.parent}.${target.name}` : target.name;
    throw new Error(
      `SDK symbol is ambiguous: ${target.kind} ${requested} matches ${candidates.join(', ')}; qualify it with its package`
    );
  }
  if (matches[0] || target.namespace !== undefined) return matches[0];
  // The slug/title heuristic covers converters that emit no target metadata
  // and TypeDoc members addressed through their namespace (`Auth.Client.login`
  // is the title, while the target only knows `parent: Client`). A page whose
  // target names a different symbol is never picked up by title.
  return reference.pages.find(
    (page) => agreesWithTarget(page.target, target) && matchesSdkPageHeuristic(page, target)
  );
}

function agreesWithTarget(pageTarget: SdkPageTarget | undefined, target: SdkTargetRequest) {
  if (!pageTarget) return true;
  if (pageTarget.kind !== target.kind || pageTarget.name !== target.name) return false;
  if (!target.parent) return pageTarget.parent === undefined;
  return pageTarget.parent !== undefined && `.${target.parent}`.endsWith(`.${pageTarget.parent}`);
}

export function renderSdkTarget(reference: SdkReference, target: SdkTargetRequest): SdkPage {
  const page = findSdkPage(reference, target);
  if (!page) {
    const qualified = target.parent ? `${target.parent}.${target.name}` : target.name;
    throw new Error(`SDK symbol not found: ${target.kind} ${qualified}`);
  }
  return page;
}
